import fs from 'node:fs';
const F = process.env.F ?? 'C:/Users/usuario/Documents/tutorflow-lightsout-juan-esteban-ciro-medina/.claude/worktrees/agent-a08871c598dea9445/diag-logs/diag.jsonl';
const filtro = process.argv[2] ?? '';
const verbose = process.argv[3] === 'v';
const lines = fs.readFileSync(F, 'utf8').split('\n').filter(Boolean).map(l => JSON.parse(l));
const by = new Map();
for (const l of lines) { if (!by.has(l.peticion)) by.set(l.peticion, []); by.get(l.peticion).push(l); }
let k = 0;
for (const [id, evs] of by) {
  const ini = evs.find(e => e.tipo === 'inicio');
  if (!ini || !ini.datos.pregunta.includes(filtro)) continue;
  k++;
  console.log(`\n=== #${k} ${ini.datos.usuario} | ${ini.datos.pregunta}`);
  for (const e of evs) {
    const d = e.datos;
    switch (e.tipo) {
      case 'entrada_modelo': console.log('  SECCIONES:', JSON.stringify(d.secciones)); if (verbose) console.log('  MSG0:', d.mensaje_inicial); break;
      case 'modelo_turno': console.log('  MODELO_TURNO:', JSON.stringify({ texto: d.texto, llamadas: d.llamadas, rechazada: d.rechazada })); break;
      case 'herramienta': console.log('  HERRAMIENTA:', d.Nombre, d.ArgumentosJson, verbose ? '\n' + d.resultado : '(' + d.resultado.length + ' chars)'); break;
      case 'texto_crudo': console.log('  CRUDO:', JSON.stringify(d.texto), '\n  REGLAS_REG:', JSON.stringify(d.reglas)); break;
      case 'seg10_diag': console.log('  SEG10_DIAG:', JSON.stringify(d)); break;
      case 'seg10_verificador_salida': console.log('  SEG10_RES:', d.Resultado, JSON.stringify(d.citas)); break;
      case 'citas_candidatas': console.log('  CANDIDATAS:', JSON.stringify(d)); break;
      case 'cierre_citas': console.log('  CIERRE:', JSON.stringify(d)); break;
      case 'referencia': console.log('  REF:', JSON.stringify(d)); break;
      case 'limpieza_d37': if (d.antes !== d.despues) console.log('  D37:', JSON.stringify(d)); break;
      case 'final': console.log('  FINAL:', d.resultado, JSON.stringify(d.texto), JSON.stringify(d.citas)); break;
      default: if (e.tipo.includes('FALLA')) console.log('  FALLA:', e.tipo, JSON.stringify(d));
    }
  }
}

